const webhook = $input.first()?.json || {};
const body = webhook.body && typeof webhook.body === 'object' ? webhook.body : {};
const headers = Object.fromEntries(Object.entries(webhook.headers || {}).map(([key, value]) => [String(key).toLowerCase(), value]));
const expectedKey = String($env.JAVEDAI_WORKFLOW_KEY || '').trim();
const presentedKey = String(headers['x-javedai-key'] || '').trim();
const DRY_RUN = true;

function safeEqual(left, right) {
  if (!left || !right || left.length !== right.length) return false;
  let mismatch = 0;
  for (let index = 0; index < left.length; index += 1) mismatch |= left.charCodeAt(index) ^ right.charCodeAt(index);
  return mismatch === 0;
}
function clean(value, max = 160) {
  return String(value || '').replace(/[\u0000-\u001F\u007F]/g, ' ').replace(/\s+/g, ' ').trim().slice(0, max);
}

const query = clean(body.query || body.industry || body.niche, 120);
const location = clean(body.location || body.area, 160);
const requestedPageSize = Number(body.page_size || body.max_results || 10);
const pageSize = Math.max(1, Math.min(20, Number.isFinite(requestedPageSize) ? Math.floor(requestedPageSize) : 10));
const requestedRating = Number(body.min_rating || 0);
const minRating = Math.max(0, Math.min(5, Number.isFinite(requestedRating) ? requestedRating : 0));
const includedType = clean(body.included_type, 80);
const errors = [];
if (!expectedKey) errors.push('server_auth_not_configured');
if (!safeEqual(presentedKey, expectedKey)) errors.push('unauthorized');
if (query.length < 2) errors.push('query_required');
if (location.length < 2) errors.push('location_required');
const textQuery = [query, location].filter(Boolean).join(' in ');

return [{ json: { auth_valid: safeEqual(presentedKey, expectedKey), valid: errors.length === 0, errors, dry_run: DRY_RUN, request_id: clean(body.request_id, 120) || 'company-' + Date.now().toString(36), received_at: new Date().toISOString(), search: { query, location, text_query: textQuery, page_size: pageSize, min_rating: minRating, included_type: includedType } } }];

const data = $input.first().json;
const key = [data.search.query, data.search.location, data.search.included_type, data.search.min_rating].join('|').toLowerCase();
const store = $getWorkflowStaticData('global');
store.recent_searches = store.recent_searches || {};
const now = Date.now();
const ttlMs = 15 * 60 * 1000;
for (const [storedKey, timestamp] of Object.entries(store.recent_searches)) {
  if (!Number.isFinite(timestamp) || now - timestamp > ttlMs) delete store.recent_searches[storedKey];
}
const duplicate = Boolean(store.recent_searches[key]);
if (!duplicate) store.recent_searches[key] = now;
return [{ json: { ...data, duplicate, search_key: key, idempotency_window_minutes: 15 } }];

const response = $input.first().json || {};
const context = $node['Check Search Idempotency'].json;
const places = Array.isArray(response.places) ? response.places : [];
function hostname(url) {
  try { return new URL(url).hostname.toLowerCase().replace(/^www\./, ''); } catch { return ''; }
}
const normalized = places.map((place) => {
  const website = String(place.websiteUri || '').trim();
  const domain = hostname(website);
  const rating = Number(place.rating || 0);
  const reviewCount = Number(place.userRatingCount || 0);
  let score = 0;
  score += Math.min(30, rating * 6);
  score += Math.min(25, Math.log10(reviewCount + 1) * 10);
  if (domain) score += 20;
  if (place.internationalPhoneNumber || place.nationalPhoneNumber) score += 10;
  if (place.businessStatus === 'OPERATIONAL') score += 10;
  if (place.regularOpeningHours) score += 5;
  return {
    company_id: String(place.id || ''),
    company_name: String(place.displayName?.text || '').trim(),
    domain,
    website,
    phone: String(place.internationalPhoneNumber || place.nationalPhoneNumber || ''),
    address: String(place.formattedAddress || ''),
    primary_type: String(place.primaryType || ''),
    types: Array.isArray(place.types) ? place.types : [],
    rating,
    review_count: reviewCount,
    latitude: Number(place.location?.latitude || 0),
    longitude: Number(place.location?.longitude || 0),
    google_maps_url: String(place.googleMapsUri || ''),
    business_status: String(place.businessStatus || ''),
    rank_score: Math.round(score),
    eligible_for_prospecting: Boolean(domain && place.businessStatus !== 'CLOSED_PERMANENTLY'),
    source: 'google_places_text_search'
  };
});
const seen = new Set();
const companies = normalized.filter((company) => {
  const key = company.domain || company.company_id || (company.company_name + '|' + company.address).toLowerCase();
  if (!key || seen.has(key)) return false;
  seen.add(key);
  return true;
}).sort((left, right) => right.rank_score - left.rank_score).slice(0, context.search.page_size);
return [{ json: { response: { ok: true, status: 'complete', dry_run: false, request_id: context.request_id, search: context.search, company_count: companies.length, prospectable_count: companies.filter((company) => company.eligible_for_prospecting).length, companies } } }];
